use crate::roles::RoleSignal;

/// What a spell says about a player's role, or `None` for one the
/// table does not curate.
pub(crate) fn signal(spell_id: u32) -> Option<RoleSignal> {
    let i = TABLE.binary_search_by_key(&spell_id, |e| e.0).ok()?;
    let &(_, code) = TABLE.get(i)?;
    RoleSignal::from_code(code)
}

