#[cfg(test)]
mod tests {
    /// Strictly ascending: binary search demands it, and it doubles as
    /// a dedup check.
    #[test]
    fn table_is_sorted_by_spell_id() {
        assert!(super::TABLE.windows(2).all(|w| w[0].0 < w[1].0));
    }

    /// Every code in the table names a kind, and a stranger is `None`.
    #[test]
    fn every_entry_resolves() {
        assert!(super::TABLE.iter().all(|e| super::signal(e.0).is_some()));
        assert_eq!(super::signal(0), None);
    }
}
